22	const PROCESSING_FEE = 5;
23	
24	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	};
28	
29	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
30	
31	const addPercent = (amount: number, percent: number): number =>
32	  amount + (amount * percent) / 100;
33	
34	export const runScenario = (scenario: Scenario): ScenarioResults => {
35	  const results = scenario.steps.map((step) => {
36	    const items = step.items ?? [];
37	    const basePremium = items.reduce(
38	      (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type],
39	      0,
40	    );
41	    const premium =
42	      addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
43	    return { premium };
44	  });
45	
46	  return { results };
47	};
