const basePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);

const calculatePremium = (items: Item[]): number =>
  addPercent(basePremiumOf(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
  PROCESSING_FEE;

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({
    premium: calculatePremium(step.items ?? []),
  })),
});
